:root {
  --bg: #1e1e2f;
  --panel: #2a2a40;
  --text: #f0f0f5;
  --accent: #6c63ff;
  --accent-hover: #5a52d5;
  --danger: #ff4d6d;
  --success: #4caf50;
  --border: #3a3a55;
  --radius: 12px;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: var(--font);
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.app {
  width: 100%;
  max-width: 480px;
  background: var(--panel);
  border-radius: var(--radius);
  padding: 24px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
}

h1 {
  margin: 0 0 24px;
  font-size: 1.5rem;
  text-align: center;
  letter-spacing: 0.5px;
}

.panel { display: flex; flex-direction: column; gap: 20px; }
.hidden { display: none; }

.card-form {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

label { font-weight: 600; }

input[type="text"] {
  padding: 12px;
  font-size: 1rem;
  border: 2px solid var(--border);
  border-radius: 8px;
  background: var(--bg);
  color: var(--text);
  transition: border-color 0.2s;
}

input[type="text"]:focus {
  outline: none;
  border-color: var(--accent);
}

fieldset {
  border: 2px solid var(--border);
  border-radius: 8px;
  padding: 8px 12px;
  display: flex;
  gap: 16px;
}

legend { font-weight: 600; padding: 0 4px; }

fieldset label {
  display: flex;
  align-items: center;
  gap: 6px;
  font-weight: 400;
  cursor: pointer;
}

input[type="radio"] { accent-color: var(--accent); }

.btn {
  padding: 12px 16px;
  font-size: 1rem;
  font-weight: 600;
  border: none;
  border-radius: 8px;
  background: var(--border);
  color: var(--text);
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
}

.btn:hover { background: var(--accent-hover); }
.btn:focus-visible { outline: 3px solid var(--accent); outline-offset: 2px; }
.btn:active { transform: scale(0.97); }
.btn:disabled { opacity: 0.5; cursor: not-allowed; }
.btn:disabled:hover { background: var(--border); }

.btn-primary { background: var(--accent); }
.btn-primary:hover { background: var(--accent-hover); }

.card-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
  max-height: 200px;
  overflow-y: auto;
}

.card-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 12px;
  background: var(--bg);
  border-radius: 8px;
  border: 1px solid var(--border);
  gap: 8px;
}

.card-item span { flex: 1; word-break: break-word; }

.card-item .answer-tag {
  font-size: 0.85rem;
  padding: 2px 8px;
  border-radius: 4px;
  background: var(--accent);
  color: #fff;
  flex: 0 0 auto;
}

.delete-btn {
  background: var(--danger);
  padding: 6px 10px;
  font-size: 0.85rem;
}

.delete-btn:hover { background: #e0435f; }

.play-card {
  background: var(--bg);
  padding: 24px;
  border-radius: 8px;
  text-align: center;
  font-size: 1.25rem;
  min-height: 80px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 2px solid var(--border);
}

.play-actions {
  display: flex;
  gap: 12px;
}

.play-actions .btn { flex: 1; }

.score {
  text-align: center;
  font-size: 1.1rem;
  margin: 0;
}

@media (max-width: 400px) {
  .app { padding: 16px; }
  h1 { font-size: 1.25rem; }
  .play-card { font-size: 1.1rem; padding: 16px; }
}

const state = {
  cards: [],
  playIndex: 0,
  correct: 0,
  playing: false
};

const makerEl = document.getElementById('maker');
const playEl = document.getElementById('play');
const formEl = document.getElementById('card-form');
const questionInput = document.getElementById('question');
const cardListEl = document.getElementById('card-list');
const startPlayBtn = document.getElementById('start-play');
const playCardEl = document.getElementById('play-card');
const scoreEl = document.getElementById('score');
const answerYesBtn = document.getElementById('answer-yes');
const answerNoBtn = document.getElementById('answer-no');
const backToMakerBtn = document.getElementById('back-to-maker');

function renderCards() {
  cardListEl.innerHTML = '';
  state.cards.forEach((card, i) => {
    const div = document.createElement('div');
    div.className = 'card-item';
    const span = document.createElement('span');
    span.textContent = card.question;
    const tag = document.createElement('span');
    tag.className = 'answer-tag';
    tag.textContent = card.answer.toUpperCase();
    const del = document.createElement('button');
    del.className = 'btn delete-btn';
    del.textContent = 'Delete';
    del.setAttribute('aria-label', `Delete card: ${card.question}`);
    del.addEventListener('click', () => {
      state.cards.splice(i, 1);
      renderCards();
      updateStartButton();
    });
    div.append(span, tag, del);
    cardListEl.appendChild(div);
  });
}

function updateStartButton() {
  startPlayBtn.disabled = state.cards.length === 0;
}

formEl.addEventListener('submit', (e) => {
  e.preventDefault();
  const question = questionInput.value.trim();
  if (!question) return;
  const answer = formEl.querySelector('input[name="answer"]:checked').value;
  state.cards.push({ question, answer });
  questionInput.value = '';
  renderCards();
  updateStartButton();
  questionInput.focus();
});

function startPlay() {
  state.playIndex = 0;
  state.correct = 0;
  state.playing = true;
  makerEl.classList.add('hidden');
  playEl.classList.remove('hidden');
  showCurrentCard();
}

function showCurrentCard() {
  if (state.playIndex >= state.cards.length) {
    finishPlay();
    return;
  }
  const card = state.cards[state.playIndex];
  playCardEl.textContent = card.question;
  scoreEl.textContent = `Score: ${state.correct} / ${state.playIndex}`;
  answerYesBtn.disabled = false;
  answerNoBtn.disabled = false;
}

function answer(value) {
  if (!state.playing) return;
  const card = state.cards[state.playIndex];
  if (value === card.answer) state.correct++;
  state.playIndex++;
  showCurrentCard();
}

function finishPlay() {
  state.playing = false;
  playCardEl.textContent = 'Quiz complete!';
  scoreEl.textContent = `Final score: ${state.correct} / ${state.cards.length}`;
  answerYesBtn.disabled = true;
  answerNoBtn.disabled = true;
}

function backToMaker() {
  state.playing = false;
  playEl.classList.add('hidden');
  makerEl.classList.remove('hidden');
  renderCards();
  updateStartButton();
}

startPlayBtn.addEventListener('click', startPlay);
answerYesBtn.addEventListener('click', () => answer('yes'));
answerNoBtn.addEventListener('click', () => answer('no'));
backToMakerBtn.addEventListener('click', backToMaker);

renderCards();
updateStartButton();
